 data jsonb := $issue22json${"ops":[{"table":"attributes","keys":["slug"],"row":{"id":"b15aed3f-d21a-545a-84f2-9d5fe00ef64e","slug":"personal-note-portability-scope","name":"Personal Note Portability Scope","description":"Editable text portability in a versioned Windows desktop sample. Attachments, links and folder structure are reported separately.","category":"workflow","value_type":"text"}},{"table":"escape_routes","keys":["slug"],"row":{"id":"945a59f0-d3ef-527f-9bb7-27802c0193af","slug":"portable-personal-notes","name":"Portable Personal Notes","description":"Compare editable text, attachments, links and folders using a small Windows desktop sample.","anchor_id":null,"status":"draft","editorially_approved":false,"last_verified_at":"2026-11-04T00:00:00Z"}},{"table":"evidence_sources","keys":["seed_key"],"row":{"id":"8afa33d1-b872-508f-9052-e3a1857ccb38","seed_key":"issue22-portability-source:obsidian","source_type":"documentation","title":"Obsidian documentation for note portability","url":"https://help.obsidian.md/Files+and+folders/How+Obsidian+stores+data","publisher":"Obsidian","retrieved_at":"2026-11-03T00:00:00Z"}},{"table":"claim_evidence","keys":["seed_key"],"row":{"id":"93fa70e1-08ce-5c4f-916e-86c444c480b0","seed_key":"issue22-portability-claim:obsidian","evidence_source_id":"8afa33d1-b872-508f-9052-e3a1857ccb38","excerpt":null,"notes":"Vendor documentation is background. Test observations are from the owner Windows sample dated 2026-11-04."}},{"table":"product_attributes","keys":["product_id","attribute_id"],"row":{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"b15aed3f-d21a-545a-84f2-9d5fe00ef64e","value_text":"Windows desktop 1.15.0. Opened the original Markdown sample as a vault. Both sample note links and the text file opened within Obsidian. Transfer to another app remains unverified.","value_boolean":null,"value_number":null,"value_enum":null,"confidence":0.9,"verification_status":"verified","last_verified_at":"2026-11-04T00:00