423"}},{"table":"escape_route_products","keys":["escape_route_id","product_id"],"row":{"escape_route_id":"945a59f0-d3ef-527f-9bb7-27802c0193af","product_id":"a36b8ca8-628d-5fb9-a149-d5d8d38c69cb","position":3,"relevance_score":null,"constraint_fit_score":null,"quality_score":null,"novelty_score":0,"editorial_note":"Research membership only. Position is for draft display."}},{"table":"evidence_sources","keys":["seed_key"],"row":{"id":"836501c4-1979-5a5a-9294-3bb8fa0b7a06","seed_key":"issue22-portability-source:affine","source_type":"documentation","title":"AFFiNE documentation for note portability","url":"https://affine.pro/blog/getting-started-with-affine","publisher":"AFFiNE","retrieved_at":"2026-11-03T00:00:00Z"}},{"table":"claim_evidence","keys":["seed_key"],"row":{"id":"b8952bc7-4ceb-5c39-b12c-84ed6b16b0d7","seed_key":"issue22-portability-claim:affine","evidence_source_id":"836501c4-1979-5a5a-9294-3bb8fa0b7a06","excerpt":null,"notes":"Vendor documentation is background. Test observations are from the owner Windows sample dated 2026-11-04."}},{"table":"product_attributes","keys":["product_id","attribute_id"],"row":{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"b15aed3f-d21a-545a-84f2-9d5fe00ef64e","value_text":"Windows desktop 0.27.4. Signed-out per-page Markdown retained headings, task states and a table. Native text attachment was absent and relative links kept fixture paths. Batch export and native page links remain untested.","value_boolean":null,"value_number":null,"value_enum":null,"confidence":0.9,"verification_status":"verified","last_verified_at":"2026-11-04T00:00:00Z"}},{"table":"product_attribute_evidence","keys":["product_id","attribute_id","claim_evidence_id"],"row":{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"b15aed3f-d21a-545a-84f2-9d5fe00ef64e","claim_evidence_id":"b8952bc7-4ceb-5c39-b12c-84ed6b16b0d7"}},{"table":"escape_route_products","keys":["escape_route_id","product_id"],"row":{"escape_route_id":"945a59f0-d3ef-527f-9bb7-27802c0193af","product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","position":4,"relevance_score":null,"constraint_fit_score":null,"quality_score":null,"novelty_score":0,"editorial_note":"Research membership only. Position is for draft display."}}],"baseline":{"claims":[{"product":"affine","attribute":"pricing-model","confidence":0.95,"value_enum":null,"value_text":"Free local editor and Cloud Basic; paid Cloud plans, an AI add-on and a one-time Believer offer have separate terms. The editor is MIT-licensed; the EE backend has separate authorization requirements for modification, compilation or redistribution. Check current plan prices and limits.","value_number":null,"value_boolean":null,"last_verified_at":"2026-10-08T00:00:00+00:00","verification_status":"verified"},{"product":"affine","attribute":"trade-off-summary","confidence":0.95,"value_enum":null,"value_text":"Native desktop local content is the offline comparison scope. Desktop and mobile feature coverage differs; Cloud sync and collaboration require connectivity. Notion HTML/Markdown import is supported but not all features map one-to-one; review converted content. Editor and EE backend licensing differ.","value_number":null,"value_boolean":null,"last_verified_at":"2026-10-08T00:00:00+00:00","verification_status":"verified"},{"product":"joplin","attribute":"pricing-model","confidence":0.9,"value_enum":null,"value_text":"Free core desktop notes; optional paid Joplin Cloud synchronization and sharing plans have separate limits.","value_number":null,"value_boolean":null,"last_verified_at":"2026-10-13T00:00:00+00:00","verification_status":"verified"},{"product":"joplin","attribute":"trade-off-summary","confidence":0.9,"value_enum":null,"value_text":"Compare personal notebook/Markdown notes. Migration and multi-device synchronization need separate setup; paid Cloud services have plan limits. No complete Notion database or team-workspace parity is established.","value_number":null,"value_boolean":null,"last_verified_at":"2026-10-13T00:00:00+00:00","verification_status":"verified"},{"product":"obsidian","attribute":"pricing-model","confidence":0.9,"value_enum":null,"value_text":"Free core application with no sign-up; Sync and Publish are optional paid services.","value_number":null,"value_boolean":null,"last_verified_at":"2026-10-13T00:00:00+00:00","verification_status":"verified"},{"product":"obsidian","attribute":"trade-off-summary","confidence":0.9,"value_enum":null,"value_text":"Local vault and Markdown note concepts require learning. Optional Sync and Publish are paid services; community extensions may add complexity. This compares basic personal notes, not full Notion databases or tested migration.","value_number":null,"value_boolean":null,"last_verified_at":"2026-10-13T00:00:00+00:00","verification_status":"verified"},{"product":"standard-notes","attribute":"pricing-model","confidence":0.9,"value_enum":null,"value_text":"Standard is free and includes plain-text notes. Advanced editors and other features have subscription tiers; paid offline activation has a separate process.","value_number":null,"value_boolean":null,"last_verified_at":"2026-11-02T00:00:00+00:00","verification_status":"verified"},{"product":"standard-notes","attribute":"trade-off-summary","confidence":0.9,"value_enum":null,"value_text":"Account-free notes are not synced. Set an Application Passcode to enable encryption in this mode; do not assume it is already enabled. Backups are your responsibility. Paid-feature activation and cloud services have separate conditions.","value_number":null,"value_boolean":null,"last_verified_at":"2026-11-02T00:00:00+00:00","verification_status":"verified"}],"products":[{"id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","name":"AFFiNE","slug":"affine","status":"published"},{"id":"6bd166ee-888f-44cb-9633-b7d1038edaa0","name":"Joplin","slug":"joplin","status":"published"},{"id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","name":"Obsidian","slug":"obsidian","status":"published"},{"id":"a36b8ca8-628d-5fb9-a149-d5d8d38c69cb","name":"Standard Notes","slug":"standard-notes","status":"published"}],"existing_routes":[],"existing_attribute_slugs":[]}}$issue22json$::jsonb;
 actual jsonb;
 op jsonb;
 expected jsonb;
 t text;
 keys_sql text;
 match_sql text;
 cols text;
 found boolean;
 same boolean;
BEGIN
 SELECT issue22_baseline INTO actual FROM (
-- Issue 22. Read-only production baseline for the four reviewed candidates.
WITH candidates AS (
  SELECT id, slug, name, status
  FROM software_discovery.products
  WHERE slug IN ('affine', 'joplin', 'obsidian', 'standard-notes')
), relevant_claims AS (
  SELECT p.slug AS product, a.slug AS attribute,
         pa.verification_status, pa.confidence, pa.last_verified_at,
         pa.value_boolean, pa.value_text, pa.value_enum, pa.value_number
  FROM candidates p
  JOIN software_discovery.product_attributes pa ON pa.product_id = p.id
  JOIN software_discovery.attributes a ON a.id = pa.attribute_id
  WHERE a.slug IN ('pricing-model', 'trade-off-summary')
     OR a.slug ~ '(portab|export|migrat|backup)'
)
SELECT jsonb_build_object(
  'products', COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.slug) FROM candidates p), '[]'::jsonb),
  'claims', COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.product, c.attribute) FROM relevant_claims c), '[]'::jsonb),
  'existing_routes', COALESCE((SELECT jsonb_agg(r.slug ORDER BY r.slug)
    FROM software_discovery.escape_routes r
    WHERE r.slug ~ '(portab|export|migrat)'), '[]'::jsonb),
  'existing_attribute_slugs', COALESCE((SELECT jsonb_agg(a.slug ORDER BY a.slug)
    FROM software_discovery.attributes a
    WHERE a.slug ~ '(portab|export|migrat|backup)'), '[]'::jsonb)
) AS issue22_baseline
 ) AS snapshot;
 IF actual IS DISTINCT FROM data->'baseline' THEN
  RAISE EXCEPTION 'Issue22 baseline drift. Refresh the baseline before continuing.';
 END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(data->'ops')  LOOP
  t=op->>'table';expected=op->'row';
  SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',value,value),' AND ') INTO keys_sql FROM jsonb_array_elements_text(op->'keys');
  SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND '),string_agg(format('%I',key),',') INTO match_sql,cols FROM jsonb_object_keys(expected) x(key);
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s),EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s AND %s)',t,t,keys_sql,t,t,keys_sql,match_sql) INTO found,same USING expected;
  IF found AND NOT same THEN RAISE EXCEPTION 'Issue22 conflicting or edited row in %; no changes committed',t; END IF;
  IF NOT found THEN EXECUTE format('INSERT INTO software_discovery.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::software_discovery.%I,$1)',t,cols,cols,t) USING expected; END IF;
 END LOOP;

 IF (SELECT count(*) FROM software_discovery.escape_route_products
     WHERE escape_route_id='945a59f0-d3ef-527f-9bb7-27802c0193af') <> 4 OR NOT EXISTS (
     SELECT 1 FROM software_discovery.escape_routes
     WHERE id='945a59f0-d3ef-527f-9bb7-27802c0193af' AND status='draft' AND NOT editorially_approved
 ) THEN
  RAISE EXCEPTION 'Issue22 draft postcondition failed';
 END IF;
 RAISE EXCEPTION USING ERRCODE='P2222', MESSAGE='Issue22 rehearsal complete';
EXCEPTION WHEN SQLSTATE 'P2222' THEN
 RAISE NOTICE 'Issue22 rehearsal complete: four draft memberships checked, all inserts rolled back.';
END $task$;
